#!/bin/sh
# Evaluate coverage against the threshold.
#
# Usage: sh scripts/check-coverage.sh [threshold]
# Expects coverage.txt in the current directory (generated by `make test`).
set -eu

THRESHOLD="${1:-85}"

# Generated code is excluded from the gate (see CONSTRAINTS.md): any Go file
# carrying a "Code generated ... DO NOT EDIT." header is tool output, not
# project code. Detection is by header so future generated files are excluded
# automatically without touching this script.
GENERATED=$(grep -rlE '^// Code generated .* DO NOT EDIT\.' --include='*.go' . 2>/dev/null | sed 's|^\./||' || true)

if [ -n "$GENERATED" ]; then
  # Match the relative path with a leading "/" so only exact file paths in
  # the profile (module/<relpath>:line) are filtered out.
  PATTERN=$(printf '%s\n' $GENERATED | sed 's/\./\\./g; s|^|/|' | awk 'NR > 1 { printf "|" } { printf "%s", $0 }')
  grep -vE "(${PATTERN}):" coverage.txt > .coverage.filtered
else
  cp coverage.txt .coverage.filtered
fi

go tool cover -func=.coverage.filtered | tail -n 1 | awk '{ print $3 }' | sed 's/%//' > .cov
COVERAGE=$(cat .cov)

echo "Current coverage: ${COVERAGE}% (generated code excluded)"
if [ 1 -eq "$(echo "$COVERAGE < $THRESHOLD" | bc -l)" ]; then
  echo "Coverage ${COVERAGE}% is below threshold of ${THRESHOLD}%"
  rm .cov .coverage.filtered
  exit 1
fi

rm .cov .coverage.filtered
echo "Coverage OK."
